mapper.select:
select f.follow_up_id, f.resident_id, r.real_name as resident_name, r.id_card_no, r.gender, r.age, r.phone_number, CONCAT( IFNULL(p.region_name, ''), IFNULL(c.region_name, ''), IFNULL(d.region_name, ''), IFNULL(s.region_name, ''), IFNULL(cm.region_name, '') ) as full_region_name, f.result_id, sr.risk_level, f.follow_up_reason, f.follow_up_status, f.tracker_user_name, f.planned_visit_count, f.actual_visit_count, f.start_date, f.end_date, f.last_visit_time, f.create_time from gc_follow_up f left join gc_resident r on f.resident_id = r.resident_id left join gc_region p on r.province_id = p.region_id left join gc_region c on r.city_id = c.region_id left join gc_region d on r.district_id = d.region_id left join gc_region s on r.street_id = s.region_id left join gc_region cm on r.community_id = cm.region_id left join gc_screening_result sr on f.result_id = sr.result_id
AND f.resident_id = #{residentId}
AND f.result_id = #{resultId}
AND f.follow_up_reason = #{followUpReason}
AND f.follow_up_status = #{followUpStatus}
AND f.tracker_user_id = #{trackerUserId}
order by f.create_time desc

mapper.update:
update gc_follow_up
follow_up_reason = #{followUpReason}, follow_up_status = #{followUpStatus}, tracker_user_id = #{trackerUserId}, tracker_user_name = #{trackerUserName}, planned_visit_count = #{plannedVisitCount}, actual_visit_count = #{actualVisitCount}, start_date = #{startDate}, end_date = #{endDate}, last_visit_time = #{lastVisitTime}, follow_up_conclusion = #{followUpConclusion}, update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark},
where follow_up_id = #{followUpId}

